SELECT q.REPORT_MONTH, q.TRANSACTIONS, q.ACTIVE_ACCOUNTS, q.GROSS_ACTIVITY_INR, q.NET_ACTIVITY_INR, q.RULE_FLAGS, q.FLAGGED_GROSS_INR, q.FLAG_RATE_PCT, q.P1_ACCOUNTS, q.TOP10_FLAGGED_GROSS_INR, q.TOP10_SHARE_PCT, CASE WHEN q.PREV_MONTH = TO_CHAR(ADD_MONTHS(TO_DATE(q.REPORT_MONTH,'YYYY-MM'),-1),'YYYY-MM') THEN 100.0*(q.TRANSACTIONS-q.PREV_TRANSACTIONS)/NULLIF(q.PREV_TRANSACTIONS,0) END AS TRANSACTIONS_MOM_PCT, CASE WHEN q.PREV_MONTH = TO_CHAR(ADD_MONTHS(TO_DATE(q.REPORT_MONTH,'YYYY-MM'),-1),'YYYY-MM') THEN 100.0*(q.GROSS_ACTIVITY_INR-q.PREV_GROSS)/NULLIF(q.PREV_GROSS,0) END AS GROSS_MOM_PCT, CASE WHEN q.PREV_MONTH = TO_CHAR(ADD_MONTHS(TO_DATE(q.REPORT_MONTH,'YYYY-MM'),-1),'YYYY-MM') THEN 100.0*(q.FLAGGED_GROSS_INR-q.PREV_FLAGGED)/NULLIF(q.PREV_FLAGGED,0) END AS FLAGGED_MOM_PCT, CASE WHEN q.PREV_MONTH = TO_CHAR(ADD_MONTHS(TO_DATE(q.REPORT_MONTH,'YYYY-MM'),-1),'YYYY-MM') THEN q.FLAG_RATE_PCT-q.PREV_FLAG_RATE END AS FLAG_RATE_CHANGE_PP FROM (SELECT p.*, LAG(REPORT_MONTH) OVER (ORDER BY REPORT_MONTH) AS PREV_MONTH, LAG(TRANSACTIONS) OVER (ORDER BY REPORT_MONTH) AS PREV_TRANSACTIONS, LAG(GROSS_ACTIVITY_INR) OVER (ORDER BY REPORT_MONTH) AS PREV_GROSS, LAG(FLAGGED_GROSS_INR) OVER (ORDER BY REPORT_MONTH) AS PREV_FLAGGED, LAG(FLAG_RATE_PCT) OVER (ORDER BY REPORT_MONTH) AS PREV_FLAG_RATE FROM (SELECT REPORT_MONTH, SUM(TRANSACTION_COUNT) AS TRANSACTIONS, COUNT(*) AS ACTIVE_ACCOUNTS, SUM(GROSS_ACTIVITY_INR) AS GROSS_ACTIVITY_INR, SUM(NET_ACTIVITY_INR) AS NET_ACTIVITY_INR, SUM(RULE_FLAGS) AS RULE_FLAGS, SUM(FLAGGED_GROSS_INR) AS FLAGGED_GROSS_INR, 100.0*SUM(RULE_FLAGS)/NULLIF(SUM(TRANSACTION_COUNT),0) AS FLAG_RATE_PCT, SUM(CASE WHEN DEMO_PRIORITY='P1' THEN 1 ELSE 0 END) AS P1_ACCOUNTS, SUM(CASE WHEN EXPOSURE_RANK<=10 THEN FLAGGED_GROSS_INR ELSE 0 END) AS TOP10_FLAGGED_GROSS_INR, 100.0*SUM(CASE WHEN EXPOSURE_RANK<=10 THEN FLAGGED_GROSS_INR ELSE 0 END)/NULLIF(SUM(FLAGGED_GROSS_INR),0) AS TOP10_SHARE_PCT FROM (SELECT a.*, ROW_NUMBER() OVER (PARTITION BY REPORT_MONTH ORDER BY FLAGGED_GROSS_INR DESC, RULE_FLAGS DESC, ACCOUNT_ID) AS EXPOSURE_RANK, SUM(FLAGGED_GROSS_INR) OVER (PARTITION BY REPORT_MONTH) AS MONTH_FLAGGED_GROSS_INR FROM ( SELECT ACCOUNT_ID, TO_CHAR(TRANSACTION_DATE,'YYYY-MM') AS REPORT_MONTH, COUNT(*) AS TRANSACTION_COUNT, SUM(ABS(AMOUNT)) AS GROSS_ACTIVITY_INR, SUM(AMOUNT) AS NET_ACTIVITY_INR, AVG(RISK_SCORE) AS AVG_RULE_SCORE, SUM(CASE WHEN RISK_SCORE > 60 THEN 1 ELSE 0 END) AS RULE_FLAGS, SUM(CASE WHEN RISK_SCORE > 60 THEN ABS(AMOUNT) ELSE 0 END) AS FLAGGED_GROSS_INR, 100.0 * SUM(CASE WHEN RISK_SCORE > 60 THEN 1 ELSE 0 END) / COUNT(*) AS FLAG_RATE_PCT, SUM(CASE WHEN RISK_SCORE > 60 AND ABS(AMOUNT) >= 5000 THEN 1 ELSE 0 END) AS HIGH_VALUE_FLAGS, CASE WHEN SUM(CASE WHEN RISK_SCORE > 60 THEN ABS(AMOUNT) ELSE 0 END) >= 10000 OR MAX(CASE WHEN RISK_SCORE >= 85 AND ABS(AMOUNT) >= 5000 THEN 1 ELSE 0 END) = 1 THEN 'P1' WHEN SUM(CASE WHEN RISK_SCORE > 60 THEN 1 ELSE 0 END) > 0 THEN 'P2' ELSE 'P3' END AS DEMO_PRIORITY FROM GOLD.FRAUD_DETECTION_MODEL_GOLD GROUP BY ACCOUNT_ID, TO_CHAR(TRANSACTION_DATE,'YYYY-MM') ) a) GROUP BY REPORT_MONTH) p) q
